head.script:
/*
 * WAEA-954 검증 샘플 - gridView footer setFooterClass / getFooterClass / removeFooterClass
 *
 * [전제] hotfix(2026_0701_hotfix_WAEA_954.js)가 config.js의 WebSquare.engine.module에 등록되어 있어야 한다.
 *
 * [필수 검증 4항목]
 *   1. setFooterClass("fAmt", "classA classB")  -> footer cell td에 classA, classB 적용
 *   2. getFooterClass("fAmt")                   -> 유지 중인 class 문자열 반환
 *   3. removeFooterClass("fAmt", "classA")      -> classA만 제거, classB 유지
 *   4. drawTypeX="hybrid" 그리드에서 footer redraw 후에도 동적 class 유지
 */
var FOOTER_ID = "fAmt";

scwin.onpageload = function() {
    var jsonData = [
        {"item":"상품A", "qty":10, "amt":150000},
        {"item":"상품B", "qty":5,  "amt":80000},
        {"item":"상품C", "qty":8,  "amt":120000}
    ];
    dataList1.setJSON(jsonData);
    dataList2.setJSON(jsonData);

    if (typeof gridView1.setFooterClass !== "function") {
        scwin.log("[전제 실패] gridView.setFooterClass 미제공. hotfix 미적용 상태입니다.");
    } else {
        scwin.log("hotfix 적용 확인됨. 1~4번 버튼을 순서대로 누르세요.");
    }
};

scwin.log = function(msg) {
    txtLog.setValue(txtLog.getValue() + msg + "\n");
};

// 그리드 DOM에서 해당 class를 가진 엘리먼트 개수를 센다.
// 엔진 내부 렌더 클래스(.gridFooterTableDefault)에 의존하지 않기 위해 class 자체로 조회한다.
scwin.countClass = function(gridId, className) {
    var root = document.getElementById(gridId);
    if (!root) return "(root 없음)";
    return root.querySelectorAll("." + className).length;
};

scwin.dumpState = function(gridId, grid) {
    scwin.log("  getFooterClass('" + FOOTER_ID + "') = '" + grid.getFooterClass(FOOTER_ID) + "'");
    scwin.log("  DOM classA=" + scwin.countClass(gridId, "classA") +
              ", classB=" + scwin.countClass(gridId, "classB"));
};

// 1. set
scwin.btnSetFooterClass_onclick = function(e) {
    gridView1.setFooterClass(FOOTER_ID, "classA classB");
    scwin.log("[1] setFooterClass('" + FOOTER_ID + "', 'classA classB')");
    scwin.dumpState("gridView1", gridView1);
    scwin.log("  기대: classA=1, classB=1");
};

// 2. get
scwin.btnGetFooterClass_onclick = function(e) {
    scwin.log("[2] getFooterClass -> '" + gridView1.getFooterClass(FOOTER_ID) + "'");
    scwin.log("  기대: classA classB");
};

// 3. remove (classA만)
scwin.btnRemoveFooterClass_onclick = function(e) {
    gridView1.removeFooterClass(FOOTER_ID, "classA");
    scwin.log("[3] removeFooterClass('" + FOOTER_ID + "', 'classA')");
    scwin.dumpState("gridView1", gridView1);
    scwin.log("  기대: classA=0, classB=1 / getFooterClass='classB'");
};

// 4. hybrid redraw 후 class 유지
scwin.btnHybridRedraw_onclick = function(e) {
    gridView2.setFooterClass(FOOTER_ID, "classA classB");
    scwin.log("[4] hybrid: setFooterClass 적용");
    scwin.dumpState("gridView2", gridView2);

    dataList2.setJSON([
        {"item":"상품A", "qty":11, "amt":160000},
        {"item":"상품B", "qty":6,  "amt":90000},
        {"item":"상품C", "qty":9,  "amt":130000}
    ]);
    scwin.log("  데이터 재설정으로 footer redraw 발생");
    scwin.dumpState("gridView2", gridView2);
    scwin.log("  기대: redraw 후에도 classA=1, classB=1 유지");
};

scwin.btnClear_onclick = function(e) {
    txtLog.setValue("");
};
